-- Results table for cube-semantic-tests. Generated by: python -m semtest.results --ddl <table>
-- Replace your-project.semantic_tests with your own project and dataset.
-- Not needed if suite.yml › results.bigquery.auto_create is true (the default).

CREATE TABLE IF NOT EXISTS `your-project.semantic_tests.check_results` (
  run_id STRING NOT NULL OPTIONS(description="One pytest session: CI_RUN_ID, else a generated id"),
  run_started_at TIMESTAMP NOT NULL OPTIONS(description="When the pytest session started (UTC)"),
  recorded_at TIMESTAMP NOT NULL OPTIONS(description="When this check finished (UTC)"),
  check_id STRING NOT NULL OPTIONS(description="Stable id: pytest node id, e.g. tests/data/test_parity.py::test_x[case]"),
  check_name STRING NOT NULL OPTIONS(description="Test function, e.g. test_cube_matches_reference"),
  case_id STRING OPTIONS(description="Parametrize id (case, view, persona)"),
  tier STRING OPTIONS(description="Marker tier: unit, contract, data, parity, rollup"),
  status STRING NOT NULL OPTIONS(description="pass | fail | warn | error | skip"),
  severity STRING NOT NULL OPTIONS(description="error | warn"),
  observed STRING OPTIONS(description="What Cube returned (JSON)"),
  expected STRING OPTIONS(description="What it should have been (JSON)"),
  observed_value FLOAT64 OPTIONS(description="Observed, when it is a single number (for trending)"),
  expected_value FLOAT64 OPTIONS(description="Expected, when it is a single number"),
  message STRING OPTIONS(description="Failure or skip reason, truncated"),
  owner STRING OPTIONS(description="Case `owner`, else the view's meta.owner"),
  environment STRING OPTIONS(description="SEMTEST_ENVIRONMENT, e.g. prod or the branch name"),
  duration_s FLOAT64 OPTIONS(description="Test duration in seconds"),
  git_sha STRING OPTIONS(description="GITHUB_SHA / GIT_SHA if set")
)
PARTITION BY DATE(run_started_at)
CLUSTER BY check_name, status
OPTIONS(description="Cube semantic test results, one row per check per run")
;

